import {TARGETS,proteinTarget,energyScore,progressScore,nutritionScore,wellnessScore,foodBalance,canEdit,weeklyWeighInDue,shouldCreatineRemind} from './core.js';
import {startScanner} from './scanner.js';
import {createFoodFlows,sumKnown,totalText,scaleItem,showValue,micros,nutrients,barcodeFood,cofid} from './food-flows.js';
import {recordsFromDB,mergeRecordsIntoDB,touch} from './records.js';
const KEY='optimal-v1',zone='Europe/London';
const localDate=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:zone}).format(d);
const offsetDate=n=>{const d=new Date(`${localDate()}T12:00:00`);d.setDate(d.getDate()+n);return localDate(d)};
const base=()=>({version:1,profile:null,logs:{},foods:[],weights:[],saved:[],favourites:[],recents:[],savedMeals:[],batches:[],products:[],settings:{glass:250,bottle:500},sync:{state:'Local only',pending:0}});
let db=load(),view='today',date=localDate(),stopCamera=null,sessionDismissed=false;
function load(){try{const raw=localStorage.getItem(KEY),old=JSON.parse(raw||'{}');if(!old||typeof old!=='object'||(old.logs&&(typeof old.logs!=='object'||Array.isArray(old.logs))))throw Error('Invalid saved data');return {...base(),...old,favourites:old.favourites||[],recents:old.recents||[],savedMeals:old.savedMeals||[],products:old.products||[]}}catch{return {...base(),storageError:true}}}
function persist(){if(db.storageError)return notify('Saved data could not be read. It has not been overwritten. Export or recover it before saving.');for(const r of recordsFromDB(db)){if(previousRecords.get(r.id)!==JSON.stringify(r.payload)){touch(r.payload);mergeRecordsIntoDB(db,[{...r,updatedAt:r.payload.updatedAt,revision:r.payload.revision,payload:r.payload}])}}try{localStorage.setItem(KEY,JSON.stringify(db))}catch{return notify('Device storage is full or unavailable. Export a backup before closing.')};previousRecords=new Map(recordsFromDB(db).map(x=>[x.id,JSON.stringify(x.payload)]));cloud?.enqueue();render()}
function day(d=date){return db.logs[d]||(db.logs[d]={foods:[],drinks:[],supplements:[],creatine:false,sleep:null,mood:null,workout:null})}
const editable=()=>canEdit(date,localDate());
function target(d=date){const snapshot=db.logs[d]?.targets;if(snapshot)return {...TARGETS,...snapshot};const weight=db.weights.filter(x=>!x.deletedAt&&x.date<=d).sort((a,b)=>a.date.localeCompare(b.date)).at(-1)?.lb||db.profile?.weight||146,history=db.targetHistory?.filter(x=>x.date<=d).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);return {...TARGETS,energy:history?.energy||(db.targetHistory?.length?2300:db.profile?.energyTarget||2300),protein:proteinTarget(weight)}}
function items(){return day().foods.filter(x=>!x.deletedAt).flatMap(x=>x.items||[])}
function knownTotals(){const t=sumKnown(items()).values;t.hydration=day().drinks.filter(x=>!x.deletedAt).reduce((s,x)=>s+(x.ml||0),0);return t}
function score(){return scoreDay(day(),target())}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sheet(html){lookupGeneration++;if(!document.querySelector('.panel'))sheetOrigin=document.activeElement;stopCamera?.();stopCamera=null;document.querySelector('#overlay').innerHTML=`<div class="sheet"><section class="panel" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="grab"></div>${html}</section></div>`;const title=document.querySelector('.panel h2');if(title)title.id='sheet-title';for(const x of document.querySelectorAll('.app,.bottom,.plus'))x.inert=true;document.querySelector('.panel button,.panel input,.panel textarea')?.focus()}
function close(){lookupGeneration++;stopCamera?.();stopCamera=null;document.querySelector('#overlay').innerHTML='';for(const x of document.querySelectorAll('.app,.bottom,.plus'))x.inert=false;if(sheetOrigin?.isConnected)sheetOrigin.focus();sheetOrigin=null}
function ring(name,value){const v=Number.isFinite(value)?value:'—';return `<button class="mini" data-detail="${name}" aria-label="${name} score ${v==='—'?'unavailable':`${v} out of 100`}. Open details"><span class="mini-ring ${v==='—'?'unavailable':''}" style="--p:${v==='—'?0:v};--c:${ringColour(value,name)}" aria-hidden="true"><b>${v}</b></span><small>${name}</small></button>`}
function ringColour(value,name){if(name==='Energy'&&(knownTotals().kcal??0)>target().energy*1.4)return '#c99548';if(!Number.isFinite(value))return '#59615c';if(value>=95)return '#438660';if(value>=70)return '#b4d2bf';const sufficient=score().w.known===4&&new Set(day().foods.filter(x=>!x.deletedAt).map(x=>x.type)).size>=3;return sufficient&&(date<localDate()||new Date().getHours()>=20)?'#c99548':'#a3ada6'}
function header(){const label=date===localDate()?'Today':date===offsetDate(-1)?'Yesterday':new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:zone}).format(new Date(`${date}T12:00:00`));return `<header class="top"><span class="word">OPTIMAL</span>${view==='today'?`<button class="date-button" id="date-menu"><b>${label}</b><small>${date}</small></button>`:''}</header>`}
function nav(){const icons={today:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',nutrition:'<path d="M20 3C10 2 3 6 4 13c1 7 9 8 13 3 3-4 3-9 3-13Z"/><path d="M4 21 15 10"/>',insights:'<path d="M4 3v17h17M7 15l4-5 4 2 5-7"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};return `<button class="plus" ${editable()?'':'disabled'} aria-label="Add entry">+</button><nav class="bottom" aria-label="Main navigation">${['today','nutrition','insights','profile'].map(x=>`<button class="nav ${view===x?'active':''}" data-view="${x}" ${view===x?'aria-current="page"':''}><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[x]}</svg><span>${x[0].toUpperCase()+x.slice(1)}</span></button>`).join('')}</nav><div id="overlay"></div>`}
function portionLabel(x){const name=x.displayName||x.name,g=x.grams??x.amount;if(/^bananas?$/i.test(name)&&Math.abs(g-100)<.1)return '1 medium banana';const friendly=/porridge oats/i.test(name)?'oats':/yog[uh]?urt.*greek|greek.*yog[uh]?urt/i.test(x.name)?'Greek yoghurt':name;return x.quantity+' '+friendly}
function recommendationUI(){const rec=currentRecommendation();if(!rec){const v=knownTotals(),t=target();if((v.kcal??0)>t.energy*1.1)return '<h2>Review today’s entries</h2><p>Logged energy is above your target. No additional meal is suggested.</p>';if((v.kcal??0)>=t.energy*.95&&(v.protein??0)>=t.protein*.95&&(v.fibre??0)>=t.fibre*.9)return '<h2>You’re on track</h2><p>No additional suitable meal is needed right now.</p>';return '<h2>Choose your next meal</h2><p>No reviewed suggestion fits yet. Search foods or build a meal with quantities.</p><button class="secondary" id="choose-next-meal">Review a meal</button>';}const current=items(),n=sumKnown(rec.items).values;return `<h2>${esc(rec.name)}</h2><p>${rec.items.map(x=>esc(portionLabel(x))).join(' · ')}</p><p class="recommend-totals">${totalText(rec.items)}</p><p class="projected">After this: ${totalText([...current,...rec.items])}</p><div class="recommend-actions"><button data-recommend-action="log">Log this</button><button data-recommend-action="change">Change quantities</button><button data-recommend-action="swap">Swap ingredient</button><button data-recommend-action="another">Another idea</button></div>`}
function todayPage(){const {m,n,w,bal}=score(),incomplete=w.known<4;return `${header()}<section class="wellness"><button class="overall-ring ${w.score===null?'unavailable':''}" aria-label="Wellness score ${w.score??'unavailable'}. Open details" data-detail="Wellness" style="--p:${w.score||0};--c:${(knownTotals().kcal??0)>target().energy*1.4?'#c99548':ringColour(w.score)}"><span class="overall-value">${w.score??'—'}</span><span class="overall-label">WELLNESS</span></button><div><p class="interpret">${dayInterpretation()}</p><p class="coverage">${w.known} of 4 areas assessed · provisional</p></div></section><section class="action"><span class="label">Next best action</span>${recommendationUI()}</section><section class="nutrition"><div class="score-row"><div><span class="section-title">Nutrition</span><p class="section-note">${n.known} of 4 parts assessed${bal.score===null?'':' · balance '+Math.round(bal.coverage*100)+'% covered'}</p></div><button class="nutrition-score ${n.score===null?'unavailable':''}" data-detail="Nutrition">${n.score??'—'}</button></div><div class="metrics">${ring('Protein',m.protein)}${ring('Energy',m.energy)}${ring('Fibre',m.fibre)}${ring('Hydration',m.hydration)}</div></section><section class="essentials"><span class="label">Daily essentials</span><button class="essential ${day().creatine?'done':''}" id="creatine" ${editable()?'':'disabled'}><span class="check"></span><strong>Creatine</strong><span>5 g</span></button></section>${date===localDate()&&weeklyWeighInDue(db.weights.filter(x=>!x.deletedAt).sort((a,b)=>a.date.localeCompare(b.date)),localDate())?'<section class="action"><span class="label">Weekly weigh-in</span><p>Your regular measurement is due.</p><button class="secondary" id="weight">Log weight</button></section>':''}<section class="collapsed"><details><summary>Meals <span>${day().foods.filter(x=>!x.deletedAt).length} logged</span></summary>${entries('foods')}${entries('drinks')}${entries('supplements')}</details><details><summary>Sleep <span>${day().sleep?day().sleep.hours+' hours':'Check in'}</span></summary>${editable()?'<button class="secondary" id="sleep">Add or edit check-in</button>':'<p class="coverage">Read only</p>'}</details><details><summary>FORM activity <span>${(db.formSummaries||[]).some(x=>x.endedAt&&localDate(new Date(x.endedAt))===date)?'Complete':trainingForDate(date)===100?'Rest day':'Unavailable'}</span></summary>${formDetails()}</details></section>${!editable()?'<p class="locked">Older dates are read-only.</p>':''}`}
function entries(kind){const list=(day()[kind]||[]).filter(x=>!x.deletedAt);return list.map(x=>`<div class="entry"><div><strong>${esc(x.text||x.name||'Entry')}</strong><span>${x.items?totalText(x.items):kind==='drinks'?showValue(x.ml,' ml'):esc(x.dose||'')}</span></div>${editable()?`<button data-edit-record="${kind}" data-id="${x.id}">Edit</button><button data-remove-record="${kind}" data-id="${x.id}">Delete</button>`:''}</div>`).join('')||'<p class="coverage">Nothing logged.</p>'}
function nutritionPage(){return renderNutrition()}
function insightsPage(){return renderInsights()}
function reviewUI(){const r=reviewEvidence();return `<section class="card"><h2>14-day review</h2><p>${esc(r.reason)}</p>${r.action!=='insufficient'?`<p>Trend ${r.weekly.toFixed(2)} lb/week · mean logged energy ${Math.round(r.average)} kcal · ${r.days} reliable days</p><button class="primary" id="review-accept">${r.delta?'Accept '+(r.delta>0?'+':'')+r.delta+' kcal':'Accept unchanged target'}</button><button class="secondary" id="review-keep">Keep current target</button>`:''}</section>`}
function profilePage(){return renderProfile()}
function app(){return `<div class="app">${view==='today'?todayPage():view==='nutrition'?nutritionPage():view==='insights'?insightsPage():profilePage()}</div>${nav()}`}
function addSheet(){sheet(`<h2>Add</h2><div class="options">${['Food','Snack','Drink','Supplement'].map(x=>`<button class="option" data-add="${x}">${x}</button>`).join('')}</div><button class="secondary close">Cancel</button>`)}
function foodSheet(type='Food'){sheet(`<h2>${type}</h2><div class="flow-actions"><button id="describe-meal">Describe meal</button><button id="search-picker">Search product</button><button id="scan-flow">Scan barcode</button><button id="label-flow">Enter label</button><button id="library-flow">Use saved or recent</button><button id="batch-flow">Use batch</button></div><button class="secondary close">Cancel</button>`);bindButton('#describe-meal',()=>flows.describe(type,commitMeal));bindButton('#search-picker',()=>flows.picker(item=>flows.review({name:item.name,type,items:[item]},commitMeal),()=>foodSheet(type)));bindButton('#scan-flow',()=>scanForProduct(p=>flows.productEditor(p,item=>flows.review({name:item.name,type,items:[item]},commitMeal),()=>foodSheet(type))));bindButton('#label-flow',()=>flows.productEditor({},item=>flows.review({name:item.name,type,items:[item]},commitMeal),()=>foodSheet(type)));bindButton('#library-flow',()=>flows.library(commitMeal));bindButton('#batch-flow',batchMenu)}
function scannerIntro(){sheet(`<h2>Scan barcode</h2><p>The rear camera starts only after you tap Use camera. Camera access requires a secure HTTPS connection. You can also type a barcode.</p><button class="primary" id="start-camera">Use camera</button><label class="field">Or type barcode<input id="barcode" inputmode="numeric" autocomplete="off"></label><button class="secondary" id="lookup-barcode">Look up barcode</button><button class="secondary close">Cancel</button>`)}
async function camera(){sheet(`<h2>Scan barcode</h2><div class="scanner"><video id="scanner-video" playsinline muted></video><div class="aim"></div></div><p id="scan-status" class="coverage">Point the camera at an EAN or UPC barcode.</p><button class="secondary close">Cancel</button>`);const video=document.querySelector('#scanner-video'),controller=new AbortController();stopCamera=()=>controller.abort();try{const stop=await startScanner(video,code=>{if(!controller.signal.aborted)productLookup(code)},error=>{if(!controller.signal.aborted){close();notify('Camera stopped: '+error.message)}},controller.signal);if(controller.signal.aborted||!video.isConnected)stop();else stopCamera=()=>{controller.abort();stop()}}catch(e){if(controller.signal.aborted)return;sheet(`<h2>Camera unavailable</h2><p>${e.name==='NotAllowedError'?'Camera permission was denied.':'No usable rear camera was found.'}</p><label class="field">Type barcode<input id="barcode" inputmode="numeric"></label><button class="primary" id="lookup-barcode">Look up</button><button class="secondary" id="manual-label">Enter label manually</button><button class="secondary close">Cancel</button>`)}}
async function productLookup(query){if(!/^(?:\d{8}|\d{12}|\d{13})$/.test(query))return notify('Enter an 8, 12 or 13-digit EAN/UPC barcode.');const callback=scanCallback;scanCallback=null;sheet(`<h2>Looking up barcode</h2><p>${esc(query)}</p><button class="secondary close">Cancel</button>`);const generation=lookupGeneration;try{const p=await barcodeFood(query,db);if(generation!==lookupGeneration)return;if(callback)callback(p);else productReview(p)}catch(e){if(generation!==lookupGeneration)return;const p={barcode:query,source:'Product label'};notify(e.message+' · Enter the package label.');if(callback)callback(p);else productReview(p)}}
function productReview(p){flows.productEditor(p,item=>flows.review({name:item.name,type:'Food',items:[item]},commitMeal),()=>foodSheet())}
function manualLabel(barcode='',reason=''){if(reason)notify(reason);const callback=scanCallback;scanCallback=null;const product={barcode,source:'Product label'};if(callback)callback(product);else productReview(product)}
function batchMenu(){sheet(`<h2>Batch meals</h2><button class="primary" id="new-reviewed-batch">Create batch</button><div class="pick-list">${db.batches.filter(x=>!x.deletedAt).map(x=>`<div class="review-item"><strong>${esc(x.name)}</strong><p>${x.finished?'Finished':x.yieldG+'g estimated yield'} · version ${x.version||1}</p>${!x.finished?`<button data-portion-batch="${x.id}">Log portion</button>`:''}<button data-edit-batch="${x.id}">Edit recipe</button><button data-copy-batch="${x.id}">Duplicate recipe</button><button data-finish-batch="${x.id}">${x.finished?'Reopen':'Mark finished'}</button></div>`).join('')}</div><button class="secondary close">Close</button>`);bindButton('#new-reviewed-batch',()=>editBatch());for(const b of document.querySelectorAll('[data-portion-batch],[data-edit-batch],[data-copy-batch],[data-finish-batch]'))b.onclick=e=>{e.stopImmediatePropagation();const id=Object.values(b.dataset)[0],x=db.batches.find(y=>y.id===id);if(b.dataset.portionBatch)portionSheet(x);else if(b.dataset.editBatch)editBatch(x);else if(b.dataset.copyBatch)editBatch({...structuredClone(x),id:null,name:x.name+' (new batch)',version:0});else{touch(x);x.finished=!x.finished;persist();batchMenu()}}}
function portionSheet(b){sheet(`<h2>${esc(b.name)}</h2><form id="portion-form"><label class="field">Portion eaten (g)<input name="portion" type="number" min="1" max="${b.yieldG}" step="any" required></label><p class="coverage">Keeps a snapshot of recipe version ${b.version||1}. Add sides in the next review.</p><button class="primary">Review portion and sides</button></form><button class="secondary close">Cancel</button>`);document.querySelector('#portion-form').onsubmit=e=>{e.preventDefault();const amount=+new FormData(e.target).get('portion'),factor=amount/b.yieldG,part=structuredClone(b),portionItems=b.ingredients.map(x=>({...scaleItem(x,factor),batchSnapshot:part,batchPortionG:amount}));flows.review({name:amount+'g '+b.name,type:'Food',items:portionItems,batchSnapshot:part},commitMeal)}}
function detail(name){showDetail(name)}
function render(){if(!db.profile){document.querySelector('#app').innerHTML=onboarding();bind();return}document.querySelector('#app').innerHTML=app();bind();if(shouldCreatineRemind({hour:Number(new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',hourCycle:'h23'}).format(new Date())),taken:day(localDate()).creatine,dismissedSession:sessionDismissed})&&date===localDate())sheet(`<h2>Creatine reminder</h2><p>Your 5g creatine is not logged today.</p><button class="primary" id="takecreatine">Mark taken</button><button class="secondary" id="dismiss">Not now</button>`)}
function onboarding(){return profileForm(false)}
function bind(){
 bindCompletedFlows();
 document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{view=x.dataset.view;render();window.scrollTo(0,0)});
 bindButton('.plus',()=>{if(editable())addSheet()});
 document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>detail(x.dataset.detail));
 bindButton('#date-menu',()=>sheet(`<h2>Choose date</h2><button class="option" data-date="${localDate()}">Today</button><button class="option" data-date="${offsetDate(-1)}">Yesterday</button><label class="field">Older history<input id="history-date" type="date" max="${localDate()}"></label><button class="secondary" id="open-date">Open date</button><button class="secondary close">Cancel</button>`));
 bindButton('#creatine',()=>{if(!editable())return;day().creatine=!day().creatine;day().creatineRecord=touch({id:day().creatineRecord?.id,taken:day().creatine});persist()});
 bindButton('#sleep',sleepEditor);bindButton('#weight',weightEditor);
 bindButton('#export',()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.href=url;a.download=`optimal-backup-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
 document.querySelector('#overlay')?.addEventListener('click',overlayClick);
}
async function overlayClick(e){const b=e.target.closest('button');if(e.target.classList.contains('sheet')||b?.classList.contains('close'))return close();if(!b)return;
 if(b.dataset.add){if(!editable())return;if(['Food','Snack'].includes(b.dataset.add))return foodSheet(b.dataset.add);if(b.dataset.add==='Supplement')return newSupplement();if(b.dataset.add==='Drink'){const record={id:crypto.randomUUID(),name:'Water',ml:250};return newSimpleRecord('drinks',record)}}
 if(b.id==='start-camera')return camera();if(b.id==='lookup-barcode')return productLookup(document.querySelector('#barcode').value.trim());if(b.id==='manual-label')return manualLabel(document.querySelector('#barcode')?.value||'');
 if(b.dataset.date){date=b.dataset.date;close();return render()}if(b.id==='open-date'){const value=document.querySelector('#history-date').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value>localDate())return notify('Choose today or an earlier date.');date=value;close();return render()}
 if(b.id==='takecreatine'){day(localDate()).creatine=true;day(localDate()).creatineRecord=touch({id:day(localDate()).creatineRecord?.id,taken:true});close();return persist()}if(b.id==='dismiss'){sessionDismissed=true;return close()}
}
let lookupGeneration=0,sheetOrigin=null,flows,cloud=null,previousRecords=new Map(),scanCallback=null,catalog=[],ideaIndex=0,insightPeriod=7;
const bindButton=(selector,fn)=>document.querySelector(selector)?.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();fn(e)});
function notify(message){let node=document.querySelector('#toast');if(!node){node=document.createElement('p');node.id='toast';node.setAttribute('role','status');document.body.append(node)}node.textContent=message;clearTimeout(notify.timer);notify.timer=setTimeout(()=>node.remove(),6000)}
function initializeFlows(){
 initializeCloud();
 for(const key of ['saved','savedMeals','products','batches','favourites','recents','weights','reviews','targetHistory'])db[key]??=[];
 for(const [d,log]of Object.entries(db.logs)){for(const key of ['foods','drinks','supplements']){log[key]??=[];log[key].forEach((x,i)=>x.id??=`legacy:${d}:${key}:${i}`)}}
 for(const key of ['saved','savedMeals','products','batches','favourites','recents','weights'])db[key].forEach((x,i)=>x.id??=`legacy:${key}:${i}`);
 previousRecords=new Map(recordsFromDB(db).map(x=>[x.id,JSON.stringify(x.payload)]));
 flows=createFoodFlows({getDB:()=>db,sheet,save:persist,canWrite:editable,onScan:scanForProduct,notify});
 cofid().then(x=>{catalog=x;if(view==='today'&&!document.querySelector('.panel'))render()}).catch(e=>notify(e.message));
 let lastDay=localDate();setInterval(()=>{const next=localDate();if(next!==lastDay){if(date===lastDay)date=next;lastDay=next;close();render()}},15000);
 document.addEventListener('keydown',e=>{const panel=document.querySelector('.panel');if(!panel)return;if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const focus=[...panel.querySelectorAll('button,input,textarea,select,[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length);if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
}
function commitMeal(draft){if(!editable())return notify('Older dates are read-only.');const log=day();log.targets??=target();const existing=log.foods.find(x=>x.id===draft.id),record=touch({...existing,id:draft.id||crypto.randomUUID(),type:draft.type||'Food',text:draft.name,items:structuredClone(draft.items),batchSnapshot:draft.batchSnapshot||existing?.batchSnapshot,createdAt:existing?.createdAt||new Date().toISOString(),incomplete:draft.incomplete});if(existing)Object.assign(existing,record);else log.foods.push(record);db.recents.unshift(touch({id:crypto.randomUUID(),name:draft.name,items:structuredClone(draft.items)}));if(draft.savedMeal)db.savedMeals.push(touch({id:crypto.randomUUID(),name:draft.name,items:structuredClone(draft.items)}));close();persist()}
function editBatch(batch){flows.review({id:batch?.id,name:batch?.name||'New batch',items:structuredClone(batch?.ingredients||[]),batch:true,yieldG:batch?.yieldG},draft=>{const value=touch({...batch,id:draft.id||crypto.randomUUID(),name:draft.name,ingredients:draft.items,yieldG:draft.yieldG,version:(batch?.version||0)+1,finished:false,incomplete:draft.incomplete,estimated:true});const index=db.batches.findIndex(x=>x.id===value.id);if(index<0)db.batches.push(value);else db.batches[index]=value;persist();batchMenu()})}
function scanForProduct(callback){scanCallback=callback;scannerIntro()}
function scoreDay(log,t,d=date){const food=(log.foods||[]).filter(x=>!x.deletedAt).flatMap(x=>x.items||[]),v=sumKnown(food).values,bal=foodBalance(food),water=(log.drinks||[]).filter(x=>!x.deletedAt).reduce((s,x)=>s+(Number.isFinite(x.ml)?x.ml:0),0),m={protein:v.protein===null?null:progressScore(v.protein,t.protein),energy:v.kcal===null?null:energyScore(v.kcal,t.energy),fibre:v.fibre===null?null:progressScore(v.fibre,t.fibre),hydration:(log.drinks||[]).some(x=>!x.deletedAt&&Number.isFinite(x.ml)&&x.ml>0)?progressScore(water,t.hydration):null},n=nutritionScore({...m,balance:bal.score});const sleep=log.sleep&&!log.sleep.deletedAt?Math.round(Math.min(100,log.sleep.hours/7*100)*.6+((log.sleep.quality||3)/5*100)*.2+((log.sleep.energy||3)/5*100)*.2):null;return {m,n,bal,w:wellnessScore({nutrition:n.score,hydration:m.hydration,sleep,training:trainingForDate(d)})}}
function currentRecommendation(){const v=knownTotals(),t=target();if((v.kcal??0)>t.energy*1.1||((v.kcal??0)>=t.energy*.95&&(v.protein??0)>=t.protein*.95&&(v.fibre??0)>=t.fibre*.9))return null;const pool=db.savedMeals.filter(x=>!x.deletedAt).map(x=>({name:x.name,items:structuredClone(x.items),saved:true}));for(const b of db.batches.filter(x=>!x.deletedAt&&!x.finished&&x.yieldG>0))pool.push({name:b.name,saved:true,items:b.ingredients.map(x=>scaleItem(x,Math.min(350,b.yieldG)/b.yieldG))});const find=(pattern,amount)=>{const p=catalog.find(x=>pattern.test(x.name)&&Number.isFinite(x.kcal)&&Number.isFinite(x.protein));if(!p)return null;return {...scaleItem({...p,amount:100,unit:'g'},amount/100),definition:p,grams:amount,displayName:p.name.split(',')[0]}};
 for(const recipe of [{name:'Greek yoghurt, banana and oats',parts:[[/yogurt.*greek.*plain/i,200],[/^bananas.*flesh/i,100],[/^porridge oats, unfortified$/i,40]]},{name:'Chicken, rice and broccoli',parts:[[/chicken.*breast.*grilled without skin/i,150],[/rice.*white.*boiled/i,180],[/broccoli.*boiled/i,100]]}]){const list=recipe.parts.map(([p,g])=>find(p,g));if(list.every(Boolean))pool.push({name:recipe.name,items:list})}
 const suitable=pool.filter(x=>{const n=sumKnown(x.items);return n.coverage.kcal===1&&n.coverage.protein===1&&n.coverage.fibre===1&&n.values.kcal>0&&n.values.kcal<=Math.max(0,t.energy*1.1-(v.kcal??0))});suitable.sort((a,b)=>recommendationFit(a,v,t)-recommendationFit(b,v,t));return suitable.length?suitable[ideaIndex%suitable.length]:null}
function profileForm(edit){const p=db.profile||{},latest=db.weights.filter(x=>!x.deletedAt).sort((a,b)=>a.date.localeCompare(b.date)).at(-1),metric=p.units==='metric',factor=metric?1/2.2046226218:1,display=n=>Number.isFinite(n)?Math.round(n*factor*10)/10:'';return `<div class="app"><header class="top"><span class="word">OPTIMAL</span></header><h1>${edit?'Edit profile':'Welcome to OPTIMAL'}</h1><form id="profile-form" data-units="${metric?'metric':'imperial'}"><label class="field">Current weight (<span class="weight-unit">${metric?'kg':'lb'}</span>)<input name="weight" type="number" min="20" step="any" required value="${display(latest?.lb||p.weight)}"></label><label class="field">Measurement date<input name="measurement" type="date" max="${localDate()}" required value="${latest?.date||localDate()}"></label><label class="field">Height (cm)<input name="height" type="number" min="80" step="any" required value="${p.height||''}"></label><label class="field">Goal weight (<span class="weight-unit">${metric?'kg':'lb'}</span>)<input name="goal" type="number" min="20" step="any" required value="${display(p.goal)}"></label><label class="field">Date of birth<input name="dob" type="date" max="${localDate()}" required value="${p.dob||''}"></label><label class="field">Biological sex<select name="sex">${['Prefer not to say','Female','Male'].map(x=>`<option ${p.sex===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Non-training activity<select name="activity">${['Mostly seated','Lightly active','Active','Very active'].map(x=>`<option ${p.activity===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Training pattern<input name="training" required value="${esc(p.training||'')}" placeholder="e.g. Monday, Wednesday, Friday"></label><label class="field">Preferred units<select name="units"><option value="imperial" ${metric?'':'selected'}>lb / cm</option><option value="metric" ${metric?'selected':''}>kg / cm</option></select></label><p class="coverage">Starting energy stays at 2,300 kcal. Later changes require your acceptance. Protein is 0.75g per pound.</p><button class="primary">Save profile</button>${edit?'<button class="secondary" type="button" id="cancel-profile">Cancel</button>':''}</form></div>`}
function renderProfile(){return `${header()}<h1>Profile</h1><section class="profile-group"><h2>Personal details</h2><p>${esc(db.profile.units==='metric'?'Metric':'Imperial')} · ${esc(db.profile.training)}</p><button class="secondary" id="edit-profile">Edit profile</button></section><section class="profile-group"><h2>Targets and units</h2><p class="coverage">${target().energy.toLocaleString()} kcal · ${target().protein} g protein · ${esc(db.profile.units==='metric'?'kg / cm':'lb / cm')}</p><button class="secondary" id="weight">Log weight</button></section><section class="profile-group"><h2>Saved foods and meals</h2><button class="secondary" id="library-profile">Saved foods and meals</button></section><section class="profile-group"><h2>Saved batches</h2><button class="secondary" id="batch-profile">Saved batches</button></section><section class="profile-group"><h2>Account and synchronisation</h2><p id="sync-state">${esc(db.sync?.state||'Local')}${db.sync?.error?' · '+esc(db.sync.error):''} · Stored on this device</p>${cloud?`<p>${cloud.user?esc(cloud.user.email):'Sign in to your private account'}</p>${cloud.user?'<button id="sign-out" class="secondary">Sign out</button>':'<form id="sign-in"><label class="field">Email<input name="email" type="email" autocomplete="username" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Sign in</button></form>'}`:'<p class="coverage">Local mode. Firebase configuration is not installed. Export a backup before activation.</p>'}</section><section class="profile-group"><h2>Backup and restore</h2><button class="secondary" id="export">Export JSON backup</button><label class="field">Restore backup<input id="restore-safe" type="file" accept="application/json"></label></section>${reviewUI()}`}
function renderNutrition(){const v=knownTotals(),food=items(),{bal}=score();return `${header()}<h1>Nutrition</h1><p>${totalText(food)}</p><button class="secondary" data-detail="Nutrition">Score and Food Balance details</button><p class="coverage">Food Balance ${Math.round(bal.coverage*100)}% covered. Unconfirmed categories and unknown nutrients reduce coverage.</p><h2>Micronutrients</h2><p class="coverage"><a href="https://www.nhs.uk/conditions/vitamins-and-minerals/" target="_blank" rel="noopener">NHS adult reference guidance</a> · not tailored for pregnancy, children or medical treatment.</p><p class="coverage">Known amounts only; missing fields remain Unknown. Reference amounts are not upper limits or a diagnosis.</p>${Object.entries(micros).map(([k,[label,unit,reference]])=>{const supplements=day().supplements.filter(x=>!x.deletedAt).map(x=>({...x.nutrients,source:'Product label'})),sv=sumKnown(supplements).values[k],coverage=sumKnown(food).coverage[k];return `<details class="micro-row"><summary>${label}<span>${showValue(v[k],unit)}</span></summary><p>Food ${showValue(v[k],unit)} · Supplements ${showValue(sv,unit)}</p><small>Adult reference ${microReference(k,reference)}${unit}/day · ${Math.round(coverage*100)}% food coverage</small><p class="coverage">${microTrend(k,unit)}</p></details>`}).join('')}`}
function renderInsights(){const dates=Array.from({length:insightPeriod},(_,i)=>offsetDate(i-insightPeriod+1)),series={Weight:[],Wellness:[],Nutrition:[],Energy:[],Protein:[],Fibre:[],Hydration:[],'Sleep hours':[],'Sleep quality':[],'Morning energy':[],'Workout consistency':[]};for(const d of dates){const log=db.logs[d],sc=log?scoreDay(log,log.targets||target(d),d):null,weight=db.weights.filter(x=>!x.deletedAt&&x.date===d).at(-1);series.Weight.push(weight?weight.lb*(db.profile.units==='metric'?1/2.2046226218:1):null);series.Wellness.push(sc?.w.score??null);series.Nutrition.push(sc?.n.score??null);for(const k of ['Energy','Protein','Fibre','Hydration'])series[k].push(sc?.m[k.toLowerCase()]??null);series['Sleep hours'].push(log?.sleep?.hours??null);series['Sleep quality'].push(log?.sleep?.quality??null);series['Morning energy'].push(log?.sleep?.energy??null);series['Workout consistency'].push(trainingForDate(d))}return `${header()}<h1>Insights</h1><div class="flow-actions insight-periods">${[7,30,90].map(n=>`<button data-period="${n}" aria-pressed="${n===insightPeriod}">${n} days</button>`).join('')}</div><p class="coverage">${dates[0]} – ${dates.at(-1)} · gaps mean no data, never zero.</p>${Object.entries(series).sort(([a],[b])=>['Wellness','Nutrition','Energy','Protein','Fibre','Hydration','Sleep hours','Sleep quality','Morning energy','Workout consistency','Weight'].indexOf(a)-['Wellness','Nutrition','Energy','Protein','Fibre','Hydration','Sleep hours','Sleep quality','Morning energy','Workout consistency','Weight'].indexOf(b)).map(([name,values])=>{const known=values.filter(Number.isFinite),max=Math.max(1,...known),min=name==='Weight'?Math.min(...known)-1:0,summary=known.length?`${known.length} of ${insightPeriod} days · mean ${(known.reduce((s,x)=>s+x,0)/known.length).toFixed(1)}`:'No recorded data';const group={Wellness:'Scores',Energy:'Nutrition','Sleep hours':'Recovery','Workout consistency':'Training',Weight:'Weight'}[name];return `${group?'<h2 class="chart-group">'+group+'</h2>':''}${known.length<2?'<details class="sparse-trend"><summary>'+name+'<span>More data needed</span></summary>':''}<section class="trend"><h2>${name}</h2><svg viewBox="0 0 300 64" role="img" aria-label="${name}: ${summary}">${values.map((v,i)=>v===null?'':`<circle cx="${5+i*290/Math.max(1,values.length-1)}" cy="${58-(v-min)/Math.max(1,max-min)*50}" r="2.5" fill="${(db.logs[dates[i]]?.foods||[]).some(e=>(e.items||[]).some(x=>x.source==='Estimated'))?'#d5bd88':'currentColor'}"><title>${dates[i]}: ${v}</title></circle>`).join('')}</svg><p class="coverage">${summary}${name==='Weight'?db.profile.units==='metric'?' kg':' lb':''}</p><details><summary>Daily values</summary><table><thead><tr><th>Date</th><th>Value</th></tr></thead><tbody>${values.map((v,i)=>`<tr><td>${dates[i]}</td><td>${v===null?'No data':Number(v).toFixed(1)}</td></tr>`).join('')}</tbody></table></details></section>${known.length<2?'</details>':''}`}).join('')}<p class="coverage"><span class="estimated-key">Gold dots</span> include estimated food values. Grey/green dots use reported label or database values. No correlations are inferred.</p>${reviewUI()}`}
function reviewEvidence(){const last=db.reviews.at(-1);if(last&&(Date.parse(localDate())-Date.parse(last.date))/864e5<14)return {action:'insufficient',reason:'Your last review decision is saved. The next review is due after 14 days.'};const days=Object.entries(db.logs).filter(([d])=>d>=offsetDate(-14)&&d<localDate()).map(([d,l])=>{const entries=l.foods.filter(x=>!x.deletedAt),s=sumKnown(entries.flatMap(x=>x.items||[]));return {date:d,kcal:s.values.kcal,reliable:s.coverage.kcal===1&&s.coverage.protein===1&&s.values.kcal>=(l.targets?.energy||target().energy)*.7&&new Set(entries.map(x=>x.type)).size>=3&&!entries.some(x=>x.incomplete)}}).filter(x=>x.reliable);const weights=[...new Map(db.weights.filter(x=>!x.deletedAt&&x.date>=offsetDate(-28)&&x.date<=localDate()).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[x.date,x])).values()];if(days.length<10||weights.length<3||(Date.parse(weights.at(-1)?.date)-Date.parse(weights[0]?.date))/864e5<14)return {action:'insufficient',reason:'Need 10 reliable days covering multiple eating periods and at least three weigh-ins spanning 14 days. Isolated measurements are not enough.'};const slopes=[];for(let i=0;i<weights.length;i++)for(let j=i+1;j<weights.length;j++){const span=(Date.parse(weights[j].date)-Date.parse(weights[i].date))/864e5;if(span>=7)slopes.push((weights[j].lb-weights[i].lb)*7/span)}slopes.sort((a,b)=>a-b);const weekly=slopes[Math.floor(slopes.length/2)],average=days.reduce((s,x)=>s+x.kcal,0)/days.length,delta=weekly<.25?100:weekly>.5?-100:0;return {action:'review',weekly,average,days:days.length,delta,reason:`Observed trend compared with the intended 0.25–0.5 lb weekly gain. ${delta?'Consider a small energy adjustment.':'Keep the current energy target.'} No change is automatic.`}}
function showDetail(name){const t=target(),tot=knownTotals(),sc=score(),key={Protein:'protein',Energy:'kcal',Fibre:'fibre',Hydration:'hydration'}[name];if(!key){sheet(`<h2>${esc(name)}</h2><p>Score: ${name==='Wellness'?sc.w.score??'Unknown':sc.n.score??'Unknown'}</p><p>Day in progress · ${sc.w.known} of 4 Wellness areas assessed</p><h3>Why this score?</h3><p>Calculated by the existing weighted scoring engine. Unknown areas are excluded; the result remains provisional.</p><p>Food Balance uses confirmed food categories, saturated fat and free sugar (not total sugars). Coverage ${Math.round(sc.bal.coverage*100)}%. ${Object.entries(sc.bal.parts||{}).map(([key,value])=>esc(key)+': '+value+'/100').join(' · ')}</p><button class="secondary close">Close</button>`);return}const targetValue=key==='kcal'?t.energy:t[key],value=tot[key],unit=key==='kcal'?' kcal':key==='hydration'?' L':'g',factor=key==='hydration'?.001:1;const sources=key==='hydration'?day().drinks.filter(x=>!x.deletedAt).map(x=>({name:x.name,value:x.ml,meal:'Drink',source:'Logged amount'})):day().foods.filter(x=>!x.deletedAt).flatMap(meal=>(meal.items||[]).map(x=>({name:x.name,value:x[key],meal:meal.type+' · '+meal.text,source:x.source})));sheet(`<h2>${name}</h2><p>${showValue(value===null?null:value*factor,unit)} consumed</p><p>${showValue(targetValue*factor,unit)} target</p><p>${showValue(value===null?null:Math.max(0,targetValue-value)*factor,unit)} remaining</p><p>Score: ${sc.m[name.toLowerCase()]??'Unknown'}</p><p>Status: ${dayInterpretation()}</p><h3>Sources</h3>${sources.map(x=>`<div class="source-row"><strong>${esc(x.name)}</strong><p>${showValue(Number.isFinite(x.value)?x.value*factor:null,unit)} · ${esc(x.meal)}</p><small>${esc(x.source||'Unknown')}</small></div>`).join('')||'<p>No sources logged.</p>'}<h3>Why this score?</h3><p>${key==='kcal'?'Energy uses the approved target-adherence curve.':'Progress towards your daily target, capped at 100.'} Missing fields are unknown; known subtotals may be incomplete. Early-day scores are provisional.</p><button class="secondary close">Close</button>`)}
function bindCompletedFlows(){
 bindButton('#choose-next-meal',()=>foodSheet('Food'));
 document.querySelector('#sign-in')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await cloud.signIn(f.get('email'),f.get('password'));render()}catch(error){notify('Sign in failed: '+error.code)}});bindButton('#sign-out',async()=>{await cloud.signOut();render()});
 bindButton('#edit-profile',()=>{document.querySelector('#app').innerHTML=profileForm(true);bindCompletedFlows()});bindButton('#library-profile',()=>flows.library(commitMeal));bindButton('#batch-profile',batchMenu);
 const profileFormElement=document.querySelector('#profile-form');if(profileFormElement){let weightEdited=false,goalEdited=false;profileFormElement.elements.weight.oninput=()=>weightEdited=true;profileFormElement.elements.measurement.oninput=()=>weightEdited=true;profileFormElement.elements.goal.oninput=()=>goalEdited=true;profileFormElement.elements.units.onchange=e=>{const old=profileFormElement.dataset.units,next=e.target.value,ratio=(old==='metric'?2.2046226218:1)/(next==='metric'?2.2046226218:1);for(const name of ['weight','goal']){const input=profileFormElement.elements[name];if(input.value)input.value=String(Math.round(+input.value*ratio*10)/10)}profileFormElement.dataset.units=next;profileFormElement.querySelectorAll('.weight-unit').forEach(x=>x.textContent=next==='metric'?'kg':'lb')};profileFormElement.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),first=!db.profile,latest=db.weights.filter(x=>!x.deletedAt).sort((a,b)=>a.date.localeCompare(b.date)).at(-1),factor=f.get('units')==='metric'?2.2046226218:1,weight=first||weightEdited?+f.get('weight')*factor:latest?.lb||db.profile.weight,goal=first||goalEdited?+f.get('goal')*factor:db.profile.goal;db.profile=touch({...db.profile,weight,height:+f.get('height'),goal,dob:f.get('dob'),sex:f.get('sex'),activity:f.get('activity'),training:f.get('training'),units:f.get('units')});if(first||weightEdited)db.weights.push(touch({id:crypto.randomUUID(),lb:weight,date:f.get('measurement')}));persist();window.scrollTo(0,0)})}bindButton('#cancel-profile',render);
 document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{insightPeriod=+b.dataset.period;render()});
 document.querySelectorAll('[data-recommend-action]').forEach(b=>b.onclick=()=>{if(!editable())return notify('Older dates are read-only.');if(b.dataset.recommendAction==='another'){ideaIndex++;render();return}const rec=currentRecommendation();if(!rec)return;const draft={...structuredClone(rec),type:'Food',recommendation:true,currentItems:structuredClone(items())};if(b.dataset.recommendAction==='log')commitMeal(draft);else flows.review(draft,commitMeal)});
 document.querySelectorAll('[data-edit-record]').forEach(b=>b.onclick=()=>{if(!editable())return;const record=day()[b.dataset.editRecord].find(x=>x.id===b.dataset.id);if(record.items)flows.review({id:record.id,name:record.text,type:record.type,items:structuredClone(record.items)},commitMeal);else editSimpleRecord(b.dataset.editRecord,record)});
 document.querySelectorAll('[data-remove-record]').forEach(b=>b.onclick=()=>{if(editable()&&confirm('Delete this entry?')){const record=day()[b.dataset.removeRecord].find(x=>x.id===b.dataset.id);touch(record);record.deletedAt=record.updatedAt;persist()}});
 const decide=accept=>{const r=reviewEvidence();if(r.action==='insufficient')return;db.reviews.push(touch({id:crypto.randomUUID(),date:localDate(),accepted:accept,...r}));if(accept&&r.delta){const previous=target(localDate()).energy;db.profile.energyTarget=previous+r.delta;if(db.logs[localDate()]?.targets)db.logs[localDate()].targets.energy=db.profile.energyTarget;db.targetHistory.push(touch({id:crypto.randomUUID(),date:localDate(),previous,energy:db.profile.energyTarget}))}persist()};bindButton('#review-accept',()=>decide(true));bindButton('#review-keep',()=>decide(false));
 document.querySelector('#restore-safe')?.addEventListener('change',async e=>{try{const value=JSON.parse(await e.target.files[0].text());if(value.version!==1||!value.logs||typeof value.logs!=='object'||!Array.isArray(value.weights))throw Error('Not a valid OPTIMAL backup');const records=recordsFromDB(value);if(!records.every(x=>x.id&&x.payload&&typeof x.payload==='object'))throw Error('Invalid records');if(confirm(`Merge ${records.length} records? Newer local entries will be kept.`)){mergeRecordsIntoDB(db,records);persist();notify('Backup merged; newer local records retained.')}}catch(err){notify('Backup not restored: '+err.message)}});
}
function editSimpleRecord(kind,record){sheet(`<h2>Edit ${kind==='drinks'?'drink':'supplement'}</h2><form id="simple-record"><label class="field">Name<input name="name" required value="${esc(record.name)}"></label><label class="field">${kind==='drinks'?'Amount (ml)':'Serving'}<input name="amount" ${kind==='drinks'?'type="number" min="1" step="any"':''} required value="${esc(kind==='drinks'?record.ml:record.dose)}"></label>${kind==='supplements'?Object.entries(micros).map(([k,[n,u]])=>`<label class="field">${n} (${u})<input name="${k}" type="number" min="0" step="any" placeholder="Unknown" value="${record.nutrients?.[k]??''}"></label>`).join(''):''}<button class="primary">Save changes</button></form><button class="secondary close">Cancel</button>`);document.querySelector('#simple-record').onsubmit=e=>{e.preventDefault();if(!editable())return notify('Older dates are read-only.');const f=new FormData(e.target);record.name=f.get('name');if(kind==='drinks')record.ml=+f.get('amount');else{record.dose=f.get('amount');record.nutrients=Object.fromEntries(Object.keys(micros).map(k=>[k,f.get(k)===''?null:+f.get(k)]))}touch(record);close();persist()}}
function newSimpleRecord(kind,record){editSimpleRecord(kind,record);const form=document.querySelector('#simple-record'),original=form.onsubmit;form.onsubmit=e=>{if(!editable()){e.preventDefault();return notify('Older dates are read-only.')}day()[kind].push(record);original(e)}}
function newSupplement(){newSimpleRecord('supplements',{id:crypto.randomUUID(),name:'',dose:'',nutrients:{}})}
function recommendationFit(recipe,current,t){const n=sumKnown(recipe.items).values;return Math.abs(n.kcal-Math.min(600,Math.max(0,t.energy-(current.kcal??0))))*.04+Math.abs(n.protein-Math.min(35,Math.max(0,t.protein-(current.protein??0))))*3+Math.abs(n.fibre-Math.min(8,Math.max(0,t.fibre-(current.fibre??0))))*2-(recipe.saved?20:0)}
function dayInterpretation(){const {w}=score(),v=knownTotals();if((v.kcal??0)>target().energy*1.4)return 'Energy above target';const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',hourCycle:'h23'}).format(new Date()));if(w.known<4||(date===localDate()&&hour<18))return 'Day in progress';return w.score>=85?'Strongly on track':w.score>=70?'Good range':'Review your day'}
function microReference(key,fallback){const female=db.profile?.sex==='Female',male=db.profile?.sex==='Male',age=db.profile?.dob?(Date.now()-Date.parse(db.profile.dob))/315576e5:null;const ranges={vitaminA:female?'600':male?'700':'600–700',magnesium:female?'270':male?'300':'270–300',zinc:female?'7':male?'9.5':'7–9.5',iron:female&&age<50?'14.8':male||age>=50?'8.7':'8.7–14.8'};return ranges[key]||fallback}
function microTrend(key,unit){const dates=Array.from({length:7},(_,i)=>offsetDate(i-6)),values=dates.map(d=>{const log=db.logs[d];if(!log)return null;const total=sumKnown((log.foods||[]).filter(x=>!x.deletedAt).flatMap(x=>x.items||[]));return total.coverage[key]>=.7?total.values[key]:null}),known=values.filter(Number.isFinite);if(known.length<5)return '7-day trend needs at least 5 days with 70% nutrient coverage.';const mean=known.reduce((s,x)=>s+x,0)/known.length,max=Math.max(1,...known);return `7-day food mean ${showValue(mean,unit)} · ${known.length}/7 days with at least 70% coverage<svg viewBox="0 0 300 45" role="img" aria-label="Seven-day ${key} food intake; missing days are gaps">${values.map((v,i)=>v===null?'':`<circle cx="${6+i*48}" cy="${40-v/max*34}" r="3" fill="#b4d2bf"><title>${dates[i]}: ${showValue(v,unit)}</title></circle>`).join('')}</svg>`}
function trainingForDate(d){if(!db.formAvailable)return null;const summary=(db.formSummaries||[]).find(x=>x.endedAt&&localDate(new Date(x.endedAt))===d);if(summary)return summary.endedEarly?80:100;const pattern=(db.profile?.training||'').toLowerCase(),names=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'],planned=names.filter(x=>new RegExp('\\b'+x+'\\b').test(pattern));if(!planned.length)return null;const weekday=names[new Date(d+'T12:00:00Z').getUTCDay()];if(!planned.includes(weekday))return 100;if(d>=localDate())return null;const late=(Date.parse(localDate())-Date.parse(d))/864e5;return late<=1?80:late<=3?60:35}
function formDetails(){const summaries=(db.formSummaries||[]).filter(x=>x.endedAt&&localDate(new Date(x.endedAt))===date);return summaries.length?summaries.map(x=>`<div class="source-row"><strong>FORM · Programme day ${x.programmeDay}</strong><p>${esc(localDate(new Date(x.endedAt)))} · ${Number(x.durationMinutes)||0} minutes · ${x.endedEarly?'Ended early':'Completed'}</p>${(x.exercises||[]).map(e=>`<p>${esc(e.name)} · ${e.completedSets?.length||0} working sets</p>`).join('')}</div>`).join(''):'<p class="coverage">No verified FORM summary is available for this date. Unavailable workout data is not scored.</p>'}
function sleepEditor(){if(!editable())return;const record=day().sleep||{};sheet(`<h2>Sleep check-in</h2><form id="sleep-form">${[['hours','Hours',0,24,.25,7.5],['quality','Quality (1–5)',1,5,1,3],['energy','Morning energy (1–5)',1,5,1,3]].map(([k,label,min,max,step,value])=>`<label class="field">${label}<input name="${k}" type="number" required min="${min}" max="${max}" step="${step}" value="${record[k]??value}"></label>`).join('')}<button class="primary">Save check-in</button></form><button class="secondary close">Cancel</button>`);document.querySelector('#sleep-form').onsubmit=e=>{e.preventDefault();if(!editable())return notify('Older dates are read-only.');const f=new FormData(e.target);day().sleep=touch({id:record.id,hours:+f.get('hours'),quality:+f.get('quality'),energy:+f.get('energy')});close();persist()}}
function weightEditor(){const metric=db.profile?.units==='metric';sheet(`<h2>Log weight</h2><form id="weight-form"><label class="field">Weight (${metric?'kg':'lb'})<input name="weight" type="number" required min="${metric?20:40}" max="${metric?500:1100}" step="any"></label><label class="field">Measurement date<input name="date" type="date" required min="${offsetDate(-1)}" max="${localDate()}" value="${localDate()}"></label><button class="primary">Save weight</button></form><button class="secondary close">Cancel</button>`);document.querySelector('#weight-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!canEdit(f.get('date'),localDate()))return notify('Choose today or yesterday.');db.weights.push(touch({id:crypto.randomUUID(),lb:+f.get('weight')*(metric?2.2046226218:1),date:f.get('date')}));close();persist()}}
async function initializeCloud(){if(db.storageError)return;let configured=false;try{const config=await import('./firebase-config.js');configured=true;const sdk=await import('./cloud.js');cloud=await sdk.connectCloud({config:config.firebaseConfig,readRecords:()=>recordsFromDB(db),mergeRecords:records=>{if(mergeRecordsIntoDB(db,records)){localStorage.setItem(KEY,JSON.stringify(db));previousRecords=new Map(recordsFromDB(db).map(x=>[x.id,JSON.stringify(x.payload)]));if(!document.querySelector('.panel'))render()}},onState:(state,error)=>{db.sync={state,error:error||null};const status=document.querySelector('#sync-state');if(status)status.textContent=state+(error?' · '+error:'')},onWorkouts:records=>{const payloads=records.map(x=>x.payload||x),manifest=payloads.find(x=>x.kind==='manifest');db.formSummaries=payloads.filter(x=>x.kind!=='manifest');db.formAvailable=!!manifest&&manifest.ids.every(id=>db.formSummaries.some(x=>x.id===id));localStorage.setItem(KEY,JSON.stringify(db));if(view==='today'&&!document.querySelector('.panel'))render()}})}catch(error){db.sync={state:configured?'Error':'Local',error:configured?error.message:null};const status=document.querySelector('#sync-state');if(status)status.textContent=configured?'Sync unavailable · '+error.message:'Local · Stored on this device'} }
initializeFlows();
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');
// Follow Safari's visual viewport when its keyboard reduces the sheet's usable area.
if(window.visualViewport){const fit=()=>{document.documentElement.style.setProperty('--visible-height',window.visualViewport.height+'px');document.documentElement.style.setProperty('--visible-top',window.visualViewport.offsetTop+'px')};window.visualViewport.addEventListener('resize',fit);window.visualViewport.addEventListener('scroll',fit);fit()}
